expression:
local({
  level <- coalesce(as.numeric(students_2020_SQ3), as.numeric(students_2021_ck1), as.numeric(adolescents_2023_DQ1_1))
  case_when(
    level %in% c(1, 2) ~ "Not tracked",
    students_2021_고등학교유형 %in% "일반고" | as.numeric(adolescents_2023_DQ1_2) %in% 1 ~ "Academic",
    students_2021_고등학교유형 %in% "특성화고(직업)" | as.numeric(adolescents_2023_DQ1_2) %in% 3 ~ "Vocational",
    .default = "Unknown"
  )
})
